function esrBranch(i,btn){var c=document.querySelectorAll(".branch-chip");for(var k=0;k<c.length;k++){c[k].classList.remove("dist-chip-active");}btn.classList.add("dist-chip-active");var p=document.querySelectorAll(".branch-panel");for(var j=0;j<p.length;j++){p[j].classList.toggle("hidden",j!==i);}var a=document.getElementById("esr-bp-"+i);if(!a){return false;}var f=document.getElementById("esr-branch-map");if(f&&a.getAttribute("data-map")){f.src=a.getAttribute("data-map");}var h=document.getElementById("esr-info-title");if(h&&a.getAttribute("data-name")){h.textContent=a.getAttribute("data-name");}return false;}